// The Candy Dragon: scene graph, materials and animation.
//
// Geometry is generated by src/anatomy.js; this module wires it into a
// THREE.Group, adds sugar scatter, and exposes update(t) for every animated
// part (wings, head, jaw, tail, breathing, hovering sugar motes).

import * as THREE from 'three';
import {
  buildBodyGeometry, updateBodyGeometry, buildHeadGeometry, buildMouthGeometry, buildWing, bodyFrame,
  bodySample as sampleBody, tubeAlong, legChain, toes, teethGeometry, spineSpikes, tailBlade,
  headTransform, candyHorn,
} from './anatomy.js';
import { createCandyMaterials } from './materials.js';
import { buildSugarScatter, buildCrystalCrest, buildCandyDrips } from './sugar.js';
import { clamp, lerp, smoothstep, mulberry32 } from './rng.js';

export function createCandyDragon(opts = {}) {
  const materials = createCandyMaterials(opts);
  const root = new THREE.Group();
  root.name = 'CandyDragon';

  const body = new THREE.Group();
  root.add(body);

  // -------------------------------------------------------------------------
  // Torso
  // -------------------------------------------------------------------------
  const bodyGeo = buildBodyGeometry(0, { idle: 0, rings: opts.rings || 132, segments: opts.segments || 80 });
  const bodyMesh = new THREE.Mesh(bodyGeo, materials.body);
  bodyMesh.castShadow = true;
  bodyMesh.receiveShadow = true;
  body.add(bodyMesh);

  // -------------------------------------------------------------------------
  // Head
  // -------------------------------------------------------------------------
  const headGroup = new THREE.Group();
  headGroup.name = 'Head';
  const headScale = 2.25;
  const upper = new THREE.Mesh(buildHeadGeometry('upper', headScale), materials.head);
  upper.castShadow = true;
  headGroup.add(upper);

  const skull = new THREE.Mesh(buildMouthGeometry(headScale), materials.mouth);
  skull.castShadow = false;
  headGroup.add(skull);

  const jawPivot = new THREE.Group();
  jawPivot.position.set(0.25 * headScale, 0, -0.18 * headScale);
  const jawMesh = new THREE.Mesh(buildHeadGeometry('jaw', headScale), materials.jaw);
  jawMesh.position.set(-0.25 * headScale, 0, 0.18 * headScale);
  jawMesh.castShadow = true;
  jawPivot.add(jawMesh);
  headGroup.add(jawPivot);

  // Teeth
  for (const sgn of [1, -1]) {
    const upperTeeth = new THREE.Mesh(teethGeometry(sgn, 9, true, headScale), materials.tooth);
    headGroup.add(upperTeeth);
    const lowerTeeth = new THREE.Mesh(teethGeometry(sgn, 8, false, headScale), materials.tooth);
    jawPivot.add(lowerTeeth);
  }

  // Tongue
  const tongue = new THREE.Mesh(new THREE.CapsuleGeometry(0.055 * headScale, 0.5 * headScale, 4, 10), materials.tongue);
  tongue.rotation.z = Math.PI / 2;
  tongue.position.set(-0.75 * headScale, 0, -0.04 * headScale);
  jawPivot.add(tongue);

  // Horns: a crown of butterscotch candy canes.
  const hornSpecs = [
    // root, direction, bend, length, radius — swept back over the neck.
    { root: [0.2, 0.4, 0.36], dir: [-0.42, 0.3, 1.0], bend: [1, 0.06, -0.22], len: 1.02, r: 0.18, rings: 6 },
    { root: [0.0, 0.5, 0.3], dir: [-0.58, 0.42, 0.9], bend: [1, 0.03, -0.3], len: 0.72, r: 0.135, rings: 5 },
    { root: [0.19, 0.5, 0.04], dir: [-0.8, 0.38, 0.5], bend: [1, 0, -0.15], len: 0.5, r: 0.1, rings: 4 },
    { root: [0.32, 0.32, 0.12], dir: [-0.15, 0.88, 0.5], bend: [1, 0, -0.3], len: 0.44, r: 0.085, rings: 3 },
  ];
  for (const sgn of [1, -1]) {
    for (const spec of hornSpecs) {
      const geo = candyHorn(
        new THREE.Vector3(spec.root[0] * headScale, spec.root[1] * sgn * headScale, spec.root[2] * headScale),
        new THREE.Vector3(spec.dir[0], spec.dir[1] * sgn, spec.dir[2]).normalize(),
        new THREE.Vector3(spec.bend[0], spec.bend[1] * sgn, spec.bend[2]).normalize(),
        spec.len * headScale, spec.r * headScale, { rings: spec.rings, curve: 0.55 }
      );
      const m = new THREE.Mesh(geo, materials.horn);
      m.castShadow = true;
      headGroup.add(m);
    }
    // Cheek frill shards
    for (let k = 0; k < 3; k++) {
      const geo = candyHorn(
        new THREE.Vector3((0.34 + k * 0.1) * headScale, sgn * (0.42 - k * 0.06) * headScale, (0.02 - k * 0.06) * headScale),
        new THREE.Vector3(-0.25, sgn * 0.6, -0.6).normalize(),
        new THREE.Vector3(0.4, 0, -0.6).normalize(),
        (0.62 - k * 0.12) * headScale, (0.075 - k * 0.012) * headScale, { rings: 3, curve: 0.3 }
      );
      headGroup.add(new THREE.Mesh(geo, materials.spike));
    }

    // Eyes: glowing sherbet lamp + dark pupil + icing lid.
    const eye = new THREE.Group();
    eye.position.set(-0.86 * headScale, sgn * 0.4 * headScale, 0.22 * headScale);
    const ball = new THREE.Mesh(new THREE.SphereGeometry(0.105 * headScale, 22, 18), materials.eye);
    eye.add(ball);
    const pupil = new THREE.Mesh(new THREE.SphereGeometry(0.07 * headScale, 18, 14), materials.pupil);
    pupil.position.set(-0.045 * headScale, 0, 0.05 * headScale);
    pupil.scale.set(0.4, 1.7, 1);
    eye.add(pupil);
    const glint = new THREE.Mesh(new THREE.SphereGeometry(0.021 * headScale, 8, 8),
      new THREE.MeshBasicMaterial({ color: 0xffffff }));
    glint.position.set(-0.07 * headScale, 0.04 * headScale, 0.085 * headScale);
    eye.add(glint);
    const lid = new THREE.Mesh(
      new THREE.SphereGeometry(0.118 * headScale, 20, 12, 0, Math.PI * 2, 0, Math.PI * 0.55),
      materials.head
    );
    lid.rotation.x = sgn > 0 ? 0.5 : -0.5;
    lid.rotation.z = -0.16;
    eye.add(lid);
    // Candy brow
    const brow = new THREE.Mesh(
      candyHorn(new THREE.Vector3(-0.05 * headScale, 0, 0.03 * headScale),
        new THREE.Vector3(1, 0, 0.15).normalize(), new THREE.Vector3(0.2, 0, 0.6).normalize(),
        0.55 * headScale, 0.075 * headScale, { rings: 3, curve: 0.25 }), materials.horn);
    brow.position.set(-0.6 * headScale, sgn * 0.5 * headScale, 0.14 * headScale);
    brow.rotation.set(sgn * 0.5, 0, 0);
    headGroup.add(brow);
    eye.userData.side = sgn;
    headGroup.add(eye);
    if (sgn > 0) headGroup.userData.eyeL = eye;
    else headGroup.userData.eyeR = eye;

    // Nostril sugar
    const nostril = new THREE.Mesh(new THREE.SphereGeometry(0.06 * headScale, 12, 10), materials.mouth);
    nostril.position.set(-1.8 * headScale, sgn * 0.16 * headScale, 0.12 * headScale);
    nostril.scale.set(1, 1, 0.65);
    headGroup.add(nostril);
    for (let k = 0; k < 2; k++) {
      const plate = new THREE.Mesh(new THREE.ConeGeometry(0.075 * headScale, 0.24 * headScale, 4), materials.spike);
      plate.position.set((-0.3 - k * 0.22) * headScale, sgn * 0.44 * headScale, -0.06 * headScale);
      plate.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0),
        new THREE.Vector3(0.1, sgn * 0.9, -0.42).normalize());
      headGroup.add(plate);
    }
  }

  // Whisker-tendrils: spun sugar filaments trailing from the cheeks.
  for (const sgn of [1, -1]) {
    for (let k = 0; k < 2; k++) {
      const pts = [];
      for (let i = 0; i <= 9; i++) {
        const f = i / 9;
        // A short hanging curl of pulled sugar under the jaw.
        pts.push(new THREE.Vector3(
          (0.02 + f * 0.16 + k * 0.06) * headScale,
          sgn * (0.3 + Math.sin(f * 3.0) * 0.07 + k * 0.05) * headScale,
          (-0.02 - f * 0.34 - k * 0.04) * headScale
        ));
      }
      const geo = tubeAlong(pts, 0.055 * headScale, 0.012 * headScale, 8);
      headGroup.add(new THREE.Mesh(geo, materials.claw));
    }
  }

  body.add(headGroup);

  // -------------------------------------------------------------------------
  // Limbs
  // -------------------------------------------------------------------------
  const legs = [];
  const legDefs = [
    { t: 0.42, kind: 'fore', toe: 1.35 },
    { t: 0.68, kind: 'hind', toe: 1.6 },
  ];
  for (const def of legDefs) {
    for (const side of [1, -1]) {
      const chain = legChain(def.t, side, def.kind);
      const leg = new THREE.Group();
      // Limbs: raspberry hide that fades to pale sugar toward the claws.
      {
        const geo = chain.geometry;
        const pos = geo.attributes.position;
        const cols = new Float32Array(pos.count * 3);
        const paw = chain.joints[chain.joints.length - 1];
        const root = chain.joints[0];
        const span = root.distanceTo(paw) || 1;
        const deep = [0.97, 0.05, 0.26];
        const pale = [1.0, 0.45, 0.63];
        const v = new THREE.Vector3();
        for (let i = 0; i < pos.count; i++) {
          v.fromBufferAttribute(pos, i);
          const f = Math.min(1, Math.max(0, v.distanceTo(paw) / (span * 0.34)));
          const k = 0.55 * (1 - f); // subtle brightening toward the claws
          cols[i * 3] = deep[0] + (pale[0] - deep[0]) * k;
          cols[i * 3 + 1] = deep[1] + (pale[1] - deep[1]) * k;
          cols[i * 3 + 2] = deep[2] + (pale[2] - deep[2]) * k;
        }
        geo.setAttribute('color', new THREE.BufferAttribute(cols, 3));
      }
      const mesh = new THREE.Mesh(chain.geometry, materials.leg);
      mesh.castShadow = true;
      leg.add(mesh);
      const paw = chain.joints[chain.joints.length - 1];
      const frame = bodyFrame(def.t, 0, { idle: 0 });
      const toeGeo = toes(paw, new THREE.Vector3(0, 0, -1), frame.side, frame.tangent, def.toe * side * 0.78);
      const toeMesh = new THREE.Mesh(toeGeo, materials.claw);
      toeMesh.castShadow = true;
      leg.add(toeMesh);
      body.add(leg);
      legs.push({ leg, def, side, chain });
    }
  }

  // -------------------------------------------------------------------------
  // Wings
  // -------------------------------------------------------------------------
  const wings = [];
  for (const side of [1, -1]) {
    const w = buildWing({ span: opts.wingSpan || 7.4 });
    const pivot = new THREE.Group();
    // Sugar shoulder cap hides where the taffy membrane meets the hide.
    const cap = new THREE.Mesh(new THREE.SphereGeometry(0.42, 18, 14), materials.gumdrop);
    cap.scale.set(1, 1.1, 0.7);
    pivot.add(cap);
    const membrane = new THREE.Mesh(w.membrane, materials.wing);
    membrane.castShadow = true;
    pivot.add(membrane);
    const boneMeshes = [];
    for (const b of w.bones) {
      const m = new THREE.Mesh(tubeAlong(b.pts, b.r0, b.r1, 12), materials.bone);
      m.castShadow = true;
      pivot.add(m);
      boneMeshes.push(m);
    }
    // Wrist candy claws
    for (const tip of w.tipPoints) {
      const claw = new THREE.Mesh(new THREE.ConeGeometry(0.075, 0.36, 6), materials.claw);
      claw.position.copy(tip);
      claw.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), tip.clone().sub(w.wrist).normalize());
      pivot.add(claw);
    }
    body.add(pivot);
    wings.push({ pivot, side, ...w, boneMeshes });
  }

  // -------------------------------------------------------------------------
  // Crest, tail blade, sugar
  // -------------------------------------------------------------------------
  const crest = buildCrystalCrest(materials);
  body.add(crest);
  const blade = new THREE.Mesh(tailBlade(7), materials.gumdrop);
  blade.castShadow = true;
  body.add(blade);
  const drips = buildCandyDrips(materials);
  body.add(drips);

  const sugar = buildSugarScatter(materials, { count: opts.sprinkleCount || 1100, pearlCount: opts.pearlCount || 340 });
  body.add(sugar.sprinkles);
  body.add(sugar.pearls);

  // -------------------------------------------------------------------------
  // Floating sugar motes (points)
  // -------------------------------------------------------------------------
  const moteCount = opts.moteCount || 900;
  const moteGeo = new THREE.BufferGeometry();
  const motePos = new Float32Array(moteCount * 3);
  const moteCol = new Float32Array(moteCount * 3);
  const rand = mulberry32(778);
  const palette = [0xff8fc4, 0xffe08a, 0x8affd0, 0xc39bff, 0xffffff];
  const c = new THREE.Color();
  for (let i = 0; i < moteCount; i++) {
    const r = 4 + rand() * 16;
    const a = rand() * Math.PI * 2;
    motePos[i * 3] = Math.cos(a) * r;
    motePos[i * 3 + 1] = Math.sin(a) * r * 0.8 + 1;
    motePos[i * 3 + 2] = 0.5 + rand() * 13;
    c.setHex(palette[Math.floor(rand() * palette.length)]);
    moteCol[i * 3] = c.r; moteCol[i * 3 + 1] = c.g; moteCol[i * 3 + 2] = c.b;
  }
  moteGeo.setAttribute('position', new THREE.BufferAttribute(motePos, 3));
  moteGeo.setAttribute('color', new THREE.BufferAttribute(moteCol, 3));
  const moteMat = new THREE.PointsMaterial({
    size: 0.085,
    vertexColors: true,
    transparent: true,
    opacity: 0.9,
    depthWrite: false,
    blending: THREE.AdditiveBlending,
    map: materials.textures.sugar || null,
  });
  const motes = new THREE.Points(moteGeo, moteMat);
  motes.frustumCulled = false;
  root.add(motes);
  const moteBase = motePos.slice();

  // -------------------------------------------------------------------------
  // Animation
  // -------------------------------------------------------------------------
  let currentTime = 0;
  let roarValue = 0;
  const state = { jawOpen: 0, roars: 0 };

  /** External roar control (0..1), layered over the idle breath. */
  function setRoar(v) {
    roarValue = clamp(v, 0, 1);
  }

  function update(time, dt = 0.016, anim = {}) {
    const wingGain = anim.wingAmplitude === undefined ? 1 : anim.wingAmplitude;
    currentTime = time;
    const idle = 1;

    // Living hide: breathing, S-sway and tail whip update the real vertices.
    updateBodyGeometry(bodyGeo, time, { idle });

    // Head: slow look-around + breathing bob, plus a periodic roar.
    const ht = headTransform(time, { idle });
    headGroup.position.copy(ht.pos);
    headGroup.quaternion.copy(ht.quaternion);
    headGroup.position.x -= 0.02;
    headGroup.position.z += 0.34;
    // Look toward the camera-ish, gently.
    const yaw = Math.sin(time * 0.36) * 0.16 + Math.sin(time * 0.13) * 0.1;
    const nod = Math.sin(time * 0.52) * 0.05;
    headGroup.rotateY(yaw);
    headGroup.rotateX(nod);

    // Roar cycle: jaw opens on a slow pulse.
    const roarPhase = (time * 0.19) % 1;
    const roar = smoothstep(0.06, 0.18, roarPhase) * (1 - smoothstep(0.3, 0.46, roarPhase));
    state.jawOpen = lerp(state.jawOpen, Math.max(roar, roarValue), roarValue > 0 ? 0.3 : 0.12);
    jawPivot.rotation.z = -0.03 - (0.1 + state.jawOpen * 0.42);
    // Tongue licks when the mouth is closed.
    tongue.rotation.x = Math.sin(time * 1.7) * 0.1;
    // Eyes narrow when roaring; the whole head lifts.
    for (const eye of [headGroup.userData.eyeL, headGroup.userData.eyeR]) {
      if (eye) eye.scale.setScalar(1 - state.jawOpen * 0.1);
    }
    if (state.jawOpen > 0.02) {
      headGroup.rotateX(-state.jawOpen * 0.075);
    }

    // Wings: slow majestic beat with a held open pose.
    wings.forEach((w, i) => {
      const phase = time * 0.8 + (w.side > 0 ? 0 : 0.06);
      const beat = Math.sin(phase) * 0.5 + Math.sin(phase * 0.5 + 1.2) * 0.22;
      const anchor = bodyFrame(0.44, time, { idle });
      // The shoulder sits high on the back and slightly behind the ribs.
      const shoulder = anchor.sample.pos.clone()
        .addScaledVector(anchor.up, anchor.sample.rz * 0.95)
        .addScaledVector(anchor.side, anchor.sample.rx * 0.3 * w.side);
      w.pivot.position.copy(shoulder);

      const flap = beat * 0.16 * wingGain;
      const sweep = Math.sin(phase * 0.6) * 0.08 * wingGain;
      const basis = new THREE.Matrix4().makeBasis(
        anchor.side.clone().multiplyScalar(w.side),
        anchor.tangent.clone(),
        anchor.up.clone()
      );
      if (w.side < 0) basis.multiply(new THREE.Matrix4().makeScale(1, 1, -1)); // mirror handedness
      const q = new THREE.Quaternion().setFromRotationMatrix(basis);
      const flapQ = new THREE.Quaternion().setFromAxisAngle(anchor.tangent.clone(), flap * w.side);
      const sweepQ = new THREE.Quaternion().setFromAxisAngle(anchor.up.clone(), (-0.5 + sweep) * w.side);
      w.pivot.quaternion.copy(sweepQ).multiply(flapQ).multiply(q);
      // Membrane flex: subtle scale pulse so the taffy looks alive.
      const flex = 1 + Math.sin(phase * 1.4) * 0.012;
      w.pivot.scale.setScalar(flex);
      void i;
    });

    // Limbs and tail blade are authored in the rest pose, so they ride along
    // with the body by the delta between the rest and current spine frames.
    // Limbs are baked in the rest pose; ride them along with the spine delta.
    legs.forEach(({ leg, def }) => {
      const rest = bodyFrame(def.t, 0, { idle: 0 });
      const now = bodyFrame(def.t, time, { idle });
      leg.position.copy(now.sample.pos).sub(rest.sample.pos);
    });

    {
      const rest = bodyFrame(0.985, 0, { idle: 0 });
      const now = bodyFrame(0.985, time, { idle });
      blade.position.copy(now.sample.pos).sub(rest.sample.pos);
      const restQ = new THREE.Quaternion().setFromRotationMatrix(
        new THREE.Matrix4().makeBasis(rest.side, rest.tangent, rest.up)
      );
      const nowQ = new THREE.Quaternion().setFromRotationMatrix(
        new THREE.Matrix4().makeBasis(now.side, now.tangent, now.up)
      );
      // Rotate about the tail tip so the fin swings with the whip.
      blade.position.copy(now.sample.pos).sub(rest.sample.pos);
      blade.quaternion.copy(nowQ).multiply(restQ.invert());
      const pivot = rest.sample.pos.clone().sub(now.sample.pos);
      blade.position.add(pivot.clone().applyQuaternion(blade.quaternion).multiplyScalar(-1));
    }

    // Crest, drips and candy drips follow the hide they sit on.
    {
      const rest = bodyFrame(0.5, 0, { idle: 0 });
      const now = bodyFrame(0.5, time, { idle });
      crest.position.copy(now.sample.pos).sub(rest.sample.pos).multiplyScalar(0.6);
      drips.position.copy(now.sample.pos).sub(rest.sample.pos).multiplyScalar(0.5);
    }

    // Sugar scatter follows the skin.
    sugar.update(time, idle);

    // Motes drift.
    const attr = moteGeo.attributes.position;
    for (let i = 0; i < moteCount; i++) {
      const bx = moteBase[i * 3], by = moteBase[i * 3 + 1], bz = moteBase[i * 3 + 2];
      const ph = i * 0.37;
      attr.setXYZ(
        i,
        bx + Math.sin(time * 0.25 + ph) * 0.8,
        by + Math.cos(time * 0.21 + ph * 1.3) * 0.7,
        bz + ((time * 0.28 + ph) % 14) - 2
      );
    }
    attr.needsUpdate = true;
  }

  update(0, 0);

  return {
    root,
    materials,
    body,
    head: headGroup,
    jaw: jawPivot,
    wings,
    update,
    setRoar,
    get jawOpen() { return state.jawOpen; },
    get time() { return currentTime; },
    dispose() {
      root.traverse((o) => {
        if (o.geometry) o.geometry.dispose();
      });
      Object.values(materials).forEach((m) => {
        if (m && m.isMaterial) m.dispose();
      });
    },
  };
}
